#pragma once
// The pixel map of Chicago under the dock's map (design: docs/superpowers/specs/2026-11-12-pixel-map-design.md; the
// mockups' docs/ideas/2026-11-12-pixel-map.js, which this ports). The map is kBasemap (basemap_data.cpp, generated by
// tools/basemap_build.py from OpenStreetMap): water, green, sand, main streets and expressways. basemapRaster turns it
// into a grid of cells, one class per cell, for a map frame; it draws nothing. Map data (c) OpenStreetMap contributors,
// ODbL 1.0.
#include <stddef.h>
#include <stdint.h>

#include "map_frame.h"

namespace cta {

enum BasemapClass : uint8_t { kLand = 0, kGreen, kSand, kWater, kSideStreet, kMainStreet, kExpressway, kClassCount };

extern const float kBasemapOrigin[2];   // lat, lon of the packed points' origin
extern const size_t kBasemapSize;
extern const uint8_t kBasemap[];

// A grid of cells: cell (i, j) covers screen x from ox + i * cell and y from oy + j * cell (at the pan it was made at).
struct BasemapGrid {
    uint8_t* cells = nullptr;   // cols * rows classes, row by row
    int cols = 0, rows = 0, ox = 0, oy = 0, cell = 3;
    uint32_t version = 0;       // changes whenever the cells do
};

// Unpacks kBasemap once (into the heap: PSRAM on the dock). False when it's missing or damaged, or memory ran out.
bool basemapLoad();

// Fills g with the map in the screen rectangle (x, y, w, h) at a pan, in cells of `cell` px, anchored to the map:
// the same ground lands in the same cell, so a pan of whole cells only moves the grid. Side streets are drawn when
// sideStreets is set and a cell is at most 33 m (the packed map has none). g.cells is (re)allocated as needed.
bool basemapRaster(const MapFrame& f, int panX, int panY, int x, int y, int w, int h, int cell, bool sideStreets,
                   BasemapGrid& g);

}  // namespace cta
